const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-83.0, 24.5]); // Southwest Florida Gulf
  const region = point.buffer(10000); // 10km buffer for regional average
  const date1 = '2004-10-30';
  const date2 = '2004-11-21';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterBounds(region)
    .select('chlor_a');

  const img1 = collection.filterDate(date1, ee.Date(date1).advance(1, 'day'));
  const img2 = collection.filterDate(date2, ee.Date(date2).advance(1, 'day'));

  const size1 = img1.size().getInfo();
  const size2 = img2.size().getInfo();

  console.log(`Oct 30, 2004 Images: ${size1}`);
  console.log(`Nov 21, 2004 Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Get first image for each date
  const image1 = ee.Image(img1.first());
  const image2 = ee.Image(img2.first());

  // 3. Processing: Mask invalid values (chlorophyll should be between 0 and 30 mg/m³)
  const maskValid = function(img) {
    return img.updateMask(img.gt(0).and(img.lt(30)));
  };

  const masked1 = maskValid(image1);
  const masked2 = maskValid(image2);

  // 4. Calculate mean and pixel count
  const reduceParams = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 4600, // MODIS L3SMI resolution ~4.6km
    maxPixels: 1e9
  };

  const stats1 = masked1.reduceRegion(reduceParams).getInfo();
  const stats2 = masked2.reduceRegion(reduceParams).getInfo();

  const mean1 = stats1.chlor_a_mean;
  const count1 = stats1.chlor_a_count;
  const mean2 = stats2.chlor_a_mean;
  const count2 = stats2.chlor_a_count;

  console.log(`Oct 30: Mean Chl = ${mean1 ? mean1.toFixed(3) : 'null'}, Valid Pixels = ${count1}`);
  console.log(`Nov 21: Mean Chl = ${mean2 ? mean2.toFixed(3) : 'null'}, Valid Pixels = ${count2}`);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validation & Final Answer
  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) || 
      mean1 < 0 || mean2 < 0 || mean1 > 30 || mean2 > 30) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (mean2 > mean1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
